"""Arena Studio Android compatibility layer (generated by arena_exe_builder).

Runs before the game on a phone. It:
  * stubs tkinter (not shipped with python-for-android) so imports succeed and
    file/message dialogs act like a cancelled dialog,
  * forces a fullscreen, scaled pygame window so the game's own coordinates are
    kept and touches map correctly,
  * turns a long-press into a right-click.
Set ARENA_ANDROID_SCALED=0 or ARENA_ANDROID_LONGPRESS=0 to disable either patch.
"""
import os
import sys
import time
import types

ON_ANDROID = "ANDROID_ARGUMENT" in os.environ or "ANDROID_PRIVATE" in os.environ


def data_dir():
    """Writable folder for projects, configs and recordings."""
    for key in ("ANDROID_PRIVATE", "ANDROID_ARGUMENT"):
        path = os.environ.get(key)
        if path and os.path.isdir(path):
            return path
    return os.getcwd()


class _StubModule(types.ModuleType):
    """Module whose unknown names are harmless stand-ins."""

    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        if name.isupper():
            return name.lower()  # tkinter constants (END, LEFT, ...) are strings
        if name[:1].isupper():
            if name.endswith(("Error", "Exception")):
                return type(name, (Exception,), {})

            def _init(self, *args, **kwargs):
                raise RuntimeError("tkinter is not available on Android")

            return type(name, (), {"__init__": _init})
        return lambda *args, **kwargs: None


def _stub_tkinter():
    try:
        import tkinter  # noqa: F401
        return False
    except Exception:
        pass
    main = _StubModule("tkinter")
    main.__path__ = []
    main.TclError = type("TclError", (Exception,), {})
    subs = {
        "filedialog": {
            "askopenfilename": lambda *a, **k: "",
            "asksaveasfilename": lambda *a, **k: "",
            "askdirectory": lambda *a, **k: "",
            "askopenfilenames": lambda *a, **k: (),
            "askopenfile": lambda *a, **k: None,
            "asksaveasfile": lambda *a, **k: None,
        },
        "messagebox": {
            "showinfo": lambda *a, **k: "ok",
            "showwarning": lambda *a, **k: "ok",
            "showerror": lambda *a, **k: "ok",
            "askyesno": lambda *a, **k: False,
            "askokcancel": lambda *a, **k: False,
            "askretrycancel": lambda *a, **k: False,
            "askquestion": lambda *a, **k: "no",
            "askyesnocancel": lambda *a, **k: None,
        },
        "simpledialog": {
            "askstring": lambda *a, **k: None,
            "askinteger": lambda *a, **k: None,
            "askfloat": lambda *a, **k: None,
        },
        "colorchooser": {"askcolor": lambda *a, **k: (None, None)},
        "ttk": {},
        "font": {},
        "scrolledtext": {},
    }
    sys.modules["tkinter"] = main
    for name, table in subs.items():
        module = _StubModule("tkinter." + name)
        for key, value in table.items():
            setattr(module, key, value)
        sys.modules["tkinter." + name] = module
        setattr(main, name, module)
    return True


def _patch_display(pygame):
    if os.environ.get("ARENA_ANDROID_SCALED", "1") == "0":
        return
    original = pygame.display.set_mode

    def set_mode(size=(0, 0), flags=0, *args, **kwargs):
        if not (flags & pygame.OPENGL):
            flags = (flags & ~pygame.RESIZABLE) | pygame.FULLSCREEN | pygame.SCALED
        return original(size, flags, *args, **kwargs)

    pygame.display.set_mode = set_mode


class LongPressBridge:
    """Left-press held still for HOLD seconds -> left-up, then right-click."""

    HOLD = 0.55
    SLOP = 14

    def __init__(self, pygame, clock=time.monotonic):
        self.pg = pygame
        self.clock = clock
        self.down = None
        self.fired = False

    def process(self, events):
        pg = self.pg
        out = []
        for event in events:
            if event.type == pg.MOUSEBUTTONDOWN and event.button == 1:
                self.down = (event.pos, self.clock())
                self.fired = False
            elif event.type == pg.MOUSEMOTION and self.down and not self.fired:
                dx = event.pos[0] - self.down[0][0]
                dy = event.pos[1] - self.down[0][1]
                if dx * dx + dy * dy > self.SLOP * self.SLOP:
                    self.down = None
            elif event.type == pg.MOUSEBUTTONUP and event.button == 1:
                swallow = self.fired
                self.down = None
                self.fired = False
                if swallow:
                    continue  # the press already became a right-click
            out.append(event)
        if self.down and not self.fired and self.clock() - self.down[1] >= self.HOLD:
            self.fired = True
            pos = self.down[0]
            make = pg.event.Event
            out.append(make(pg.MOUSEBUTTONUP, pos=pos, button=1, buttons=(0, 0, 0), touch=True))
            out.append(make(pg.MOUSEBUTTONDOWN, pos=pos, button=3, touch=True))
            out.append(make(pg.MOUSEBUTTONUP, pos=pos, button=3, buttons=(0, 0, 0), touch=True))
        return out


def _patch_events(pygame):
    if os.environ.get("ARENA_ANDROID_LONGPRESS", "1") == "0":
        return
    bridge = LongPressBridge(pygame)
    original = pygame.event.get

    def get(*args, **kwargs):
        events = original(*args, **kwargs)
        if args or kwargs:
            return events  # filtered reads are left alone
        return bridge.process(events)

    pygame.event.get = get


def install():
    """Apply every patch. Safe to call on a desktop for testing."""
    _stub_tkinter()
    try:
        import pygame
    except Exception:
        return
    _patch_display(pygame)
    _patch_events(pygame)
